<?php
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM inventory WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=db()->query('SELECT * FROM inventory ORDER BY item_name')->fetchAll();$low=array_filter($rows,fn($r)=>(float)$r['current_stock']<=(float)$r['minimum_stock']&&$r['status']==='active');
?>
<div class="page-heading"><div><div class="eyebrow">Supplies control</div><h1>Inventory</h1><p>Track oils, towels, linens, lotions, and operating supplies.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#inventoryModal"><i class="bi bi-plus-lg me-1"></i>Add item</button></div>
<?php if($low):?><div class="alert alert-warning"><strong><i class="bi bi-exclamation-triangle me-1"></i>Low stock alert</strong><?php foreach($low as $it):?><div><?=h($it['item_name'])?> — <?=h($it['current_stock'])?> <?=h($it['unit'])?> remaining (minimum <?=h($it['minimum_stock'])?>)</div><?php endforeach;?></div><?php endif;?>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Item</th><th>Category</th><th>Stock</th><th>Minimum</th><th>Unit cost</th><th>Supplier</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows)echo table_empty(8);foreach($rows as $r):?><tr><td class="fw-semibold"><?=h($r['item_name'])?><div class="small-muted"><?=h($r['expiration_date']?'Expires '.date_label($r['expiration_date']):'')?></div></td><td><?=h($r['category']?:'—')?></td><td class="fw-bold <?=((float)$r['current_stock']<=(float)$r['minimum_stock']?'text-danger':'')?>"><?=h($r['current_stock'])?></td><td><?=h($r['minimum_stock'])?></td><td><?=money($r['cost'])?></td><td><?=h($r['supplier']?:'—')?></td><td><?=status_badge($r['status'])?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?=h(app_page_url('inventory',['edit'=>$r['id']]))?>"><i class="bi bi-pencil"></i></a><button class="btn btn-sm btn-light" data-bs-toggle="modal" data-bs-target="#movement<?=$r['id']?>" title="Adjust stock"><i class="bi bi-arrow-left-right"></i></button></td></tr><?php endforeach;?></tbody></table></div></div>
<?php foreach($rows as $r):?><div class="modal fade" id="movement<?=$r['id']?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><?=post_form_start('inventory_movement',app_page_url('inventory'))?><div class="modal-header"><h5 class="modal-title">Update stock · <?=h($r['item_name'])?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="inventory_id" value="<?=$r['id']?>"><div class="mb-3"><label class="form-label">Movement</label><select class="form-select" name="movement_type"><option value="stock_in">Stock in (add)</option><option value="stock_out">Stock out (deduct)</option><option value="adjustment">Set exact stock</option></select></div><div class="mb-3"><label class="form-label">Quantity</label><input class="form-control" type="number" name="quantity" step="0.01" min="0.01" required></div><div><label class="form-label">Reason</label><input class="form-control" name="reason" placeholder="Purchase, usage, stock count"></div></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-primary">Save movement</button></form></div></div></div></div><?php endforeach;?>
<div class="modal fade" id="inventoryModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><?=post_form_start('save_inventory',app_page_url('inventory'))?><div class="modal-header"><h5 class="modal-title"><?=$edit?'Edit inventory item':'Add inventory item'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="row g-3"><div class="col-md-6"><label class="form-label">Item name *</label><input class="form-control" name="item_name" required value="<?=h($edit['item_name']??'')?>"></div><div class="col-md-6"><label class="form-label">Category</label><input class="form-control" name="category" value="<?=h($edit['category']??'')?>"></div><div class="col-md-4"><label class="form-label">Unit *</label><input class="form-control" name="unit" required placeholder="bottle, piece, pack" value="<?=h($edit['unit']??'piece')?>"></div><div class="col-md-4"><label class="form-label">Current stock</label><input class="form-control" type="number" step="0.01" min="0" name="current_stock" value="<?=h($edit['current_stock']??'0')?>"></div><div class="col-md-4"><label class="form-label">Minimum stock</label><input class="form-control" type="number" step="0.01" min="0" name="minimum_stock" value="<?=h($edit['minimum_stock']??'0')?>"></div><div class="col-md-4"><label class="form-label">Unit cost (₱)</label><input class="form-control" type="number" step="0.01" min="0" name="cost" value="<?=h($edit['cost']??'0')?>"></div><div class="col-md-4"><label class="form-label">Supplier</label><input class="form-control" name="supplier" value="<?=h($edit['supplier']??'')?>"></div><div class="col-md-4"><label class="form-label">Expiration date</label><input class="form-control" type="date" name="expiration_date" value="<?=h($edit['expiration_date']??'')?>"></div><?php if($edit):?><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=selected($edit['status'],'active')?>>Active</option><option value="inactive" <?=selected($edit['status'],'inactive')?>>Inactive</option></select></div><?php endif;?></div><div class="form-text mt-3">For ongoing stock changes, use the stock movement button in the table so adjustments are recorded in inventory history.</div></div><div class="modal-footer"><a href="<?=h(app_page_url('inventory'))?>" class="btn btn-light">Cancel</a><button class="btn btn-primary">Save item</button></form></div></div></div></div><?php if($edit):?><script>document.addEventListener('DOMContentLoaded',()=>new bootstrap.Modal(document.getElementById('inventoryModal')).show());</script><?php endif;?>
